def two_sum(nums, target):
    seen = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return [seen[complement], i]
        seen[num] = i
    return []

# Example: two_sum([2,7,11,15], 9) -> [0, 1]
# Time: O(n), Space: O(n). One pass hash map from value to index.

def group_anagrams(strs):
    groups = {}
    for s in strs:
        key = tuple(sorted(s))
        groups.setdefault(key, []).append(s)
    return list(groups.values())

# Example: group_anagrams(['eat','tea','tan','ate','nat','bat']) -> [['eat','tea','ate'],['tan','nat'],['bat']]
# Time: O(n * k log k), Space: O(n*k). Sorted string as the group key.

def contains_duplicate(nums):
    seen = set()
    for num in nums:
        if num in seen:
            return True
        seen.add(num)
    return False

# Example: contains_duplicate([1,2,3,1]) -> True
# Time: O(n), Space: O(n). Set membership check in a single pass.

def first_unique_char(s):
    count = {}
    for ch in s:
        count[ch] = count.get(ch, 0) + 1
    for ch in s:
        if count[ch] == 1:
            return ch
    return None

# Example: first_unique_char('swiss') -> 'w'
# Time: O(n), Space: O(k). Frequency map then scan for count 1.

class MySet:
    def __init__(self):
        self.map = {}
    def add(self, key):
        self.map[key] = True
    def remove(self, key):
        self.map.pop(key, None)
    def contains(self, key):
        return key in self.map

# Example: s = MySet(); s.add(1); s.contains(1) -> True; s.remove(1); s.contains(1) -> False
