def can_attend_meetings(intervals):
    starts = sorted(i[0] for i in intervals)
    ends = sorted(i[1] for i in intervals)
    for s, e in zip(starts, ends):
        if s < e:
            return False
    return True

# Example: can_attend_meetings([[0,30],[5,10],[15,20]]) -> False
# Time: O(n log n), Space: O(n). Compare sorted start/end sequences.

def max_depth_brackets(s):
    depth = 0
    best = 0
    for ch in s:
        if ch == '(':
            depth += 1
            best = max(best, depth)
        elif ch == ')':
            depth -= 1
    return best

# Example: max_depth_brackets('(1+(2*3)+((8)/4))+1') -> 3
# Time: O(n), Space: O(1). Count open/close nesting with a running depth.

def contains_nearby_almost_duplicate(nums, k):
    window = set()
    for i, num in enumerate(nums):
        window.add(num)
        if len(window) > k:
            window.remove(nums[i - k])
        for w in window:
            if abs(num - w) <= 1:
                return True
    return False

# Example: contains_nearby_almost_duplicate([1,2,3,1], 3) -> True
# Time: O(n*k) worst with a plain set; with a sorted structure O(n log k), Space: O(k). Sliding window of size k.

def is_isomorphic(s, t):
    if len(s) != len(t):
        return False
    s_map, t_map = {}, {}
    for sc, tc in zip(s, t):
        if s_map.get(sc, tc) != tc:
            return False
        if t_map.get(tc, sc) != sc:
            return False
        s_map[sc] = tc
        t_map[tc] = sc
    return True

# Example: is_isomorphic('egg', 'add') -> True
# Time: O(n), Space: O(k). Two-way character mapping.

def longest_common_prefix(strs):
    if not strs:
        return ''
    prefix = strs[0]
    for s in strs[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ''
    return prefix

# Example: longest_common_prefix(['flower','flow','flight']) -> 'f'
# Time: O(S) total characters, Space: O(1). Shrink a candidate prefix against each string.

def can_form_palindrome(s):
    odd = set()
    for ch in s:
        if ch in odd:
            odd.remove(ch)
        else:
            odd.add(ch)
    return len(odd) <= 1

# Example: can_form_palindrome('carrace') -> True
# Time: O(n), Space: O(k). Toggle membership in an odd-char set.

def four_sum(nums, target=0):
    nums.sort()
    n = len(nums)
    result = []
    for i in range(n - 3):
        if i > 0 and nums[i] == nums[i-1]:
            continue
        for j in range(i + 1, n - 2):
            if j > i + 1 and nums[j] == nums[j-1]:
                continue
            left, right = j + 1, n - 1
            while left < right:
                s = nums[i] + nums[j] + nums[left] + nums[right]
                if s == target:
                    result.append([nums[i], nums[j], nums[left], nums[right]])
                    left += 1
                    right -= 1
                    while left < right and nums[left] == nums[left-1]:
                        left += 1
                    while left < right and nums[right] == nums[right+1]:
                        right -= 1
                elif s < target:
                    left += 1
                else:
                    right -= 1
    return result

# Example: four_sum([1,0,-1,0,-2,2]) -> [[-2,-1,1,2],[-2,0,0,2],[-1,0,0,1]]
# Time: O(n^3), Space: O(1) extra. Sort + nested loops + two pointers.

from collections import Counter

def compare_bags(a, b):
    ca, cb = Counter(a), Counter(b)
    equal = [x for x in ca if ca[x] == cb.get(x)]
    differ = [x for x in ca if x in cb and ca[x] != cb[x]]
    only_a = [x for x in ca if x not in cb]
    only_b = [x for x in cb if x not in ca]
    return {'equal': equal, 'differ': differ, 'only_a': only_a, 'only_b': only_b}

# Example: compare_bags([1,2,2,3],[2,3,4]) -> {'equal':[3],'differ':[2],'only_a':[1],'only_b':[4]}
# Time: O(m+n), Space: O(m+n). Counter diff analysis.

def wildcard_match(pattern, word):
    m, n = len(pattern), len(word)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True
    for i in range(1, m + 1):
        if pattern[i-1] == '*':
            dp[i][0] = dp[i-1][0]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pattern[i-1] == '*':
                dp[i][j] = dp[i-1][j] or dp[i][j-1]
            elif pattern[i-1] == '?' or pattern[i-1] == word[j-1]:
                dp[i][j] = dp[i-1][j-1]
    return dp[m][n]

def filter_wildcards(pattern, words):
    return [w for w in words if wildcard_match(pattern, w)]

# Example: filter_wildcards('a*b', ['ab','abc','acb','']) -> ['ab', 'acb']
# Time: O(P*L) per word, Space: O(P*L). DP wildcard matcher.

from collections import deque

def max_sliding_window(nums, k):
    dq = deque()
    result = []
    for i, num in enumerate(nums):
        while dq and nums[dq[-1]] < num:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            result.append(nums[dq[0]])
    return result

# Example: max_sliding_window([1,3,-1,-3,5,3,6,7], 3) -> [3,3,5,5,6,7]
# Time: O(n), Space: O(k). Monotonic deque stores candidate maxima indices.

def most_common_word(sentence):
    words = sentence.lower().split()
    count = {}
    order = []
    for w in words:
        if w not in count:
            count[w] = 0
            order.append(w)
        count[w] += 1
    best = order[0]
    for w in order:
        if count[w] > count[best]:
            best = w
    return best

# Example: most_common_word('the cat and the hat and the mat') -> 'the'
# Time: O(n), Space: O(k). Preserve first-seen order for stable tie-breaking.
